const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const filterServices=(data,query='',category='all')=>data.categories.filter(c=>category==='all'||c.id===category).map(c=>({...c,services:c.services.filter(s=>[s.name,s.expansion,s.cue,s.use,s.compare,s.group,c.title].join(' ').toLowerCase().includes(query.trim().toLowerCase()))})).filter(c=>c.services.length);
export function mapSVG(data,selected,query=''){
 const total=data.categories.reduce((n,c)=>n+c.services.length,0);
 const counts=Object.fromEntries(filterServices(data,query).map(c=>[c.id,c.services.length]));
 const nodes=data.categories.map((c,i)=>{const left=i<7,x=left?24:794,y=16+(i%7)*91,active=c.id===selected,count=counts[c.id]||0;return `<path class="map-connector ${active?'selected':''}" d="M ${left?470:650} 322 C ${left?405:715} 322 ${left?405:715} ${y+35} ${left?326:794} ${y+35}" stroke="${c.color}"/><a href="#mindmap/${c.id}" data-category="${c.id}" class="map-node ${active?'selected':''} ${query&&!count?'dim':''}" aria-label="${esc(c.title)}, ${count} entries${active?', selected':''}"><rect x="${x}" y="${y}" width="302" height="70" rx="12"/><rect x="${x}" y="${y+13}" width="5" height="44" rx="2" fill="${c.color}" class="branch-color"/><text x="${x+20}" y="${y+29}" class="map-node-title">${esc(c.title)}</text><text x="${x+20}" y="${y+53}" class="map-node-count">${String(i+1).padStart(2,'0')} · ${count} ${query?'matches':'services & features'}</text><title>${esc(c.question)}</title></a>`}).join('');
 return `<svg viewBox="0 0 1120 650" width="1120" height="650" class="service-map-svg" role="group" aria-label="AWS service mind map: fourteen categories branch from AWS. Choose a category to explore its services."><title>AWS service memory map</title>${nodes}<rect x="470" y="280" width="180" height="84" rx="16" class="map-root"/><text x="560" y="315" text-anchor="middle" class="map-root-title">AWS</text><text x="560" y="343" text-anchor="middle" class="map-root-count">${total} memory anchors</text></svg>`;
}
export function serviceCard(s,lesson,recall){
 const answer=`<h3>${esc(s.name)}</h3>${s.expansion?`<p class="map-expansion">${esc(s.expansion)}</p>`:''}<div class="map-cue">${esc(s.cue)}</div>${recall?'':`<p><strong>Choose when · Kapan:</strong> ${esc(s.use)}</p>`}<p><strong>Distinguish · Jangan tertukar:</strong> ${esc(s.compare)}</p>${s.update?`<p class="map-update"><b>${esc(s.update.tag)}:</b> ${esc(s.update.note)} <a href="${esc(s.update.url)}" target="_blank" rel="noopener">AWS notice ↗</a></p>`:''}<div class="map-card-links"><a href="#learn/${s.lesson}">Full lesson →</a>${lesson?`<a href="#source/${lesson.start}">PDF pages ${lesson.start}–${lesson.end}</a>`:''}</div>`;
 return `<li class="memory-leaf">${recall?`<div class="recall-prompt"><span class="eyebrow">NAME THE SERVICE · TEBAK LAYANANNYA</span><p>${esc(s.use)}</p></div><details class="service-detail"><summary>Reveal service & reasoning</summary><div class="service-answer">${answer}</div></details>`:`<details class="service-detail"><summary><span class="service-name">${esc(s.name)}</span><span class="service-cue">${esc(s.cue)}</span>${s.update?'<span class="map-update-label">Current note</span>':''}</summary><div class="service-answer">${answer}</div></details>`}</li>`;
}
export function branchHTML(data,lessons,selected,query,recall){
 const categories=filterServices(data,query,query?'all':selected),count=categories.reduce((n,c)=>n+c.services.length,0),lookup=Object.fromEntries(lessons.map(l=>[l.id,l]));
 return `<div class="map-results-heading"><div><span class="eyebrow">${query?'MATCHING BRANCHES':selected==='all'?'THE COMPLETE MEMORY TREE':'EXPLORE THIS BRANCH'}</span><h2 id="branch-heading">${query?`Search: ${esc(query)}`:selected==='all'?'All services & features':esc(data.categories.find(c=>c.id===selected)?.title||'Services')}</h2></div><span role="status">${count} entries</span></div>${count?categories.map(c=>`<section class="memory-category" style="--branch:${c.color}"><div class="category-root"><h3>${esc(c.title)}</h3><p>${esc(c.question)}</p></div>${!recall?`<p class="category-mnemonic"><strong>Memory hook · Ingat:</strong> ${esc(c.memory)}</p>`:''}<div class="memory-tree">${[...new Set(c.services.map(s=>s.group))].map(group=>`<section class="memory-group"><h4>${esc(group)}</h4><ul>${c.services.filter(s=>s.group===group).map(s=>serviceCard(s,lookup[s.lesson],recall)).join('')}</ul></section>`).join('')}</div><p class="map-category-source"><a href="${esc(c.source)}" target="_blank" rel="noopener">AWS category overview ↗</a> · Lesson links give the course context.</p></section>`).join(''):'<div class="empty"><h3>No matching service</h3><p>Try a name, function, acronym, or a Bahasa keyword such as “kunci” or “antrian”.</p></div>'}`;
}
export function renderMindMap(root,data,lessons,initial='identity'){
 let selected=data.categories.some(c=>c.id===initial)||initial==='all'?initial:'identity',query='',recall=false;
 root.innerHTML=`<div class="eyebrow">CHEAT SHEET · ENGLISH × BAHASA</div><h1 class="map-title">Remember the job. Find the service.</h1><p class="map-intro">Klik cabang untuk membuka layanan. Ingat <b>category → job → decisive constraint</b>, lalu uji ingatanmu dengan menutup nama layanan.</p><div class="map-controls"><label class="map-search">Find a service or use case<input type="search" id="map-search" placeholder="e.g. S3, temporary credentials, enkripsi…"></label><label>Choose a branch<select id="map-category"><option value="all">All ${data.categories.reduce((n,c)=>n+c.services.length,0)} entries</option>${data.categories.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></label><button id="map-recall" class="button" aria-pressed="false">Guess the service</button></div><div class="map-scroll" tabindex="0" aria-label="Scrollable mind map. On small screens, use Choose a branch above."><div id="map-overview"></div></div><p class="map-caption">A study taxonomy, not a traffic-flow diagram. On mobile, swipe the map or use “Choose a branch”.</p><div class="map-recall-help hidden" id="map-recall-help"><strong>Recall mode · Sebutkan dulu jawabannya.</strong> Read the use case, say the service and why, then reveal. Return tomorrow and explain the closest alternative.</div><div class="map-tools"><button id="map-expand">Expand all answers</button><button id="map-collapse">Collapse answers</button><button id="map-print">Print this selection</button></div><div id="map-branch" tabindex="-1" aria-labelledby="branch-heading"></div><details class="map-scope"><summary>Coverage & how to memorize</summary><p>${esc(data.scope)}</p><ol><li><b>Round 1 · Organize:</b> start with one category; connect each name to its job.</li><li><b>Round 2 · Retrieve:</b> use Guess the service without reading the answer first.</li><li><b>Round 3 · Compare:</b> explain why the closest alternative fails a constraint.</li><li><b>Round 4 · Revisit:</b> repeat tomorrow and after a few days; use the existing lesson recall queue for difficult topics.</li></ol><p>Mnemonics are memory aids, not complete design rules. Product lifecycle notes checked ${esc(data.updated)}; quotas, availability and pricing can change.</p><a href="https://docs.aws.amazon.com/aws-certification/latest/solutions-architect-professional-02/sap-02-in-scope-services.html" target="_blank" rel="noopener">Official SAP-C02 service scope ↗</a></details>`;
 const by=id=>root.querySelector('#'+id);
 function draw(){by('map-overview').innerHTML=mapSVG(data,selected,query);by('map-branch').innerHTML=branchHTML(data,lessons,selected,query,recall);by('map-category').value=selected;by('map-recall').setAttribute('aria-pressed',String(recall));by('map-recall').textContent=recall?'Show service names':'Guess the service';by('map-recall-help').classList.toggle('hidden',!recall);}
 function choose(id,scroll=false){selected=id;query='';by('map-search').value='';history.replaceState(null,'','#mindmap/'+id);draw();if(scroll){by('map-branch').focus({preventScroll:true});by('map-branch').scrollIntoView({block:'start'});}}
 root.onclick=e=>{const a=e.target.closest('[data-category]');if(a&&root.contains(a)){e.preventDefault();choose(a.dataset.category,true);}};
 by('map-search').oninput=e=>{query=e.target.value;draw();};by('map-category').onchange=e=>choose(e.target.value,true);by('map-recall').onclick=()=>{recall=!recall;draw();};
 by('map-expand').onclick=()=>root.querySelectorAll('.service-detail').forEach(d=>d.open=true);by('map-collapse').onclick=()=>root.querySelectorAll('.service-detail').forEach(d=>d.open=false);
 by('map-print').onclick=()=>{const details=[...root.querySelectorAll('.service-detail')],open=details.map(d=>d.open);details.forEach(d=>d.open=true);window.addEventListener('afterprint',()=>details.forEach((d,i)=>d.open=open[i]),{once:true});window.print();};draw();
}
